<script>
    const toast = document.getElementById('toast-export');
    const triggerButtons = ['btn-export-csv', 'btn-export-xlsx'];
    const closeToast = document.getElementById('btn-close-toast');

    function showToast() {
      if (!toast) return;
      toast.classList.remove('opacity-0', 'pointer-events-none', 'translate-y-4');
      toast.classList.add('opacity-100', 'translate-y-0');
      setTimeout(() => {
        hideToast();
      }, 4000);
    }

    function hideToast() {
      if (!toast) return;
      toast.classList.add('opacity-0', 'pointer-events-none', 'translate-y-4');
      toast.classList.remove('opacity-100', 'translate-y-0');
    }

    triggerButtons.forEach(id => {
      const btn = document.getElementById(id);
      if (btn) btn.addEventListener('click', showToast);
    });

    if (closeToast) {
      closeToast.addEventListener('click', hideToast);
    }
  </script>
